package com.bank.actor;

import java.math.BigDecimal;

// Immutable message — nothing can change after it is sent.
public final class AccountMessage {
    public enum Type { DEPOSIT, WITHDRAW, STOP }
    private final Type type;
    private final BigDecimal amount;

        private AccountMessage(Type type, BigDecimal amount) { this.type = type;
        this.amount = amount; }
    public static AccountMessage deposit(BigDecimal a)  { return new AccountMessage(Type.DEPOSIT, a); }
    public static AccountMessage withdraw(BigDecimal a) { return new AccountMessage(Type.WITHDRAW, a); }
    public static AccountMessage stop()                 { return new AccountMessage(Type.STOP, null); }
    public Type getType() { return type; }
    public BigDecimal getAmount() { return amount; }
}
