package com.bank.actor;

import java.math.BigDecimal;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.logging.Logger;

// Educational actor mirroring Akka: private state, mailbox, one message at a time.
public class AccountActor implements Runnable {
    private static final Logger log = Logger.getLogger(AccountActor.class.getName());

    private final String accountId;
    private BigDecimal balance;                                   // PRIVATE state — no lock needed
    private final BlockingQueue<AccountMessage> mailbox = new LinkedBlockingQueue<>();
    private volatile boolean running = true;

    public AccountActor(String accountId, BigDecimal opening) {
        this.accountId = accountId; this.balance = opening;
    }

    // tell(): asynchronous send — never blocks the sender, just enqueues.
    public void tell(AccountMessage msg) { mailbox.add(msg); }

    @Override
    public void run() {
        while (running) {
            try {
                AccountMessage msg = mailbox.take();             // one message at a time
                handle(msg);                                     // serial → no race on balance
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); running = false;
            }
        }
    }

    // Only this single thread ever touches 'balance' → safe without lock.
    private void handle(AccountMessage msg) {
        switch (msg.getType()) {
            case DEPOSIT -> {
                balance = balance.add(msg.getAmount());
                log.info(() -> accountId + " deposit " + msg.getAmount() + " → balance " + balance);
            }
            case WITHDRAW -> {
                if (balance.compareTo(msg.getAmount()) >= 0) {
                    balance = balance.subtract(msg.getAmount());
                    log.info(() -> accountId + " withdraw " + msg.getAmount() + " → balance " + balance);
                } else {
                    log.warning(() -> accountId + " withdraw " + msg.getAmount() + " DECLINED (insufficient)");
                }
            }
            case STOP -> running = false;
        }
    }

    public BigDecimal getBalance() { return balance; }  // for demo/test visibility only
}
