package com.bank.actor;

import java.math.BigDecimal;

public class ActorDemo {
    public static void main(String[] args) throws InterruptedException {
        AccountActor rajesh = new AccountActor("SAV2001", new BigDecimal("1000000"));
        AccountActor priya  = new AccountActor("CUR3001", new BigDecimal("250000"));
        Thread tr = new Thread(rajesh, "actor-SAV2001"); tr.start();
        Thread tp = new Thread(priya,  "actor-CUR3001"); tp.start();

        // Many senders fire async messages concurrently — NO shared state, NO locks.
        Runnable loadA = () -> { for (int i = 0; i < 5; i++) rajesh.tell(AccountMessage.deposit(new BigDecimal("1000"))); };
        Runnable loadB = () -> { for (int i = 0; i < 5; i++) rajesh.tell(AccountMessage.withdraw(new BigDecimal("500"))); };
        new Thread(loadA).start();
        new Thread(loadB).start();
        priya.tell(AccountMessage.deposit(new BigDecimal("75000")));

        Thread.sleep(500);
        rajesh.tell(AccountMessage.stop());
        priya.tell(AccountMessage.stop());
        tr.join(); tp.join();

        System.out.println("Rajesh final balance: " + rajesh.getBalance());
        System.out.println("Priya final balance:  " + priya.getBalance());
    }
}
