package com.bank.actor;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.assertEquals;

class AccountActorTest {
    @Test
    void concurrentMessagesProcessedSeriallyWithoutLocks() throws InterruptedException {
        AccountActor acct = new AccountActor("SAV2001", new BigDecimal("1000"));
        Thread t = new Thread(acct, "actor-SAV2001"); t.start();

        // 1000 deposits of 1 from several sender threads
        for (int s = 0; s < 4; s++) {
            new Thread(() -> { for (int i = 0; i < 250; i++) acct.tell(AccountMessage.deposit(BigDecimal.ONE)); }).start();
        }
        Thread.sleep(500);
        acct.tell(AccountMessage.stop());
        t.join();

        assertEquals(new BigDecimal("2000"), acct.getBalance());   // 1000 + 1000 deposits
    }
}
